items.solution:
class OrderService {
  constructor(emailClient) {
    this.emailClient = emailClient;
  }

  placeOrder(order) {
    return this.emailClient.send(order.customerEmail, 'Order confirmed', `Order ${order.id} confirmed`);
  }
}

